function rewardsCart(){if(!BR().rewards)return'';if(!state.customer)return `<p><a href="/store-next/account">Sign in to view your rewards</a></p>`;const w=state.customer.wallet;return `<div class="notice"><strong>${w.available} points available · ${money(w.value_cents)}</strong><p>1 point per $1 of products after discounts. 100 points = $5 off. Points work with coupon codes and never expire.</p>${state.catalog.settings.demo?'<p>Test orders do not earn or spend real points.</p>':`<label>Points to use<input id="use-points" type="number" min="0" max="${w.available}" step="1" value="${state.points}"></label>${button('Apply points','apply-points','secondary')}`}</div>`}
function accountStoreUrl(){const slug=sessionStorage.getItem('glow_customer_store')||'';return /^[a-z0-9-]+$/.test(slug)?storeUrl(slug):'/store-next/'}
function ledgerTable(entries){return entries.length?`<div class="tablewrap"><table><thead><tr><th>Date</th><th>Activity</th><th>Points</th><th>Held change</th><th>Balance</th><th>Order / note</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${new Date(e.created*1000).toLocaleString()}</td><td>${esc(e.kind.replaceAll('_',' '))}</td><td>${e.points>0?'+':''}${e.points}</td><td>${e.reserved_delta>0?'+':''}${e.reserved_delta}</td><td>${e.balance_after}</td><td>${esc(e.order_id||e.note)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No points transactions yet.</p>'}
async function loadAccount(){if(!state.catalog){state.catalog=await api('/api/catalog');renderMode(state.catalog.settings)}try{state.customer=await api('/api/account');renderAccount()}catch{state.customer=null;renderAccountLogin()}}
function renderAccountLogin(){app.innerHTML=`<div class="intro"><div class="eyebrow">Your ${esc(BR().name)} account</div><h1>Your orders. Your rewards.</h1><p class="muted">Earn 1 point per $1 of products after discounts, excluding shipping and tax. 100 points = $5 off. Points never expire.</p></div><div class="split"><form id="customer-login" class="panel"><h2>Sign in</h2><p class="muted">First visit to our new store? Your previous website password did not transfer. Use <a href="#customer-forgot">Set up or reset your password</a> below with the email from your previous orders.</p><label>Email<input name="email" type="email" autocomplete="username" required maxlength="150"></label><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><button type="submit">Sign in</button><p class="error" role="alert"></p><p class="muted">${state.catalog?.settings.email_enabled?'Use the setup / reset form below to choose your password.':'Forgot your password? Contact the store for a private reset link sent to your account email.'}</p></form><form id="customer-register" class="panel"><h2>Request an account</h2><label>Name<input name="name" autocomplete="name" required maxlength="150"></label><label>Email<input name="email" type="email" autocomplete="email" required maxlength="150"></label><button type="submit">Request account setup</button><p class="error" role="alert"></p><p class="muted">${state.catalog?.settings.email_enabled?'A private setup link will be emailed to you. Check your inbox and spam folder.':'Staff will provide a private setup link to your email. Automatic email delivery is not enabled yet.'} Use the same email as your previous orders to claim a migrated balance after verification.</p></form></div>${state.catalog?.settings.email_enabled?`<form id="customer-forgot" class="panel account-ledger"><h2>Set up or reset your password</h2><p>Existing customers: enter the email you used for your orders. We’ll email a private link to activate your account or reset your password. Your imported rewards stay with that email.</p><label>Account email<input name="email" type="email" autocomplete="email" required maxlength="150"></label><button type="submit">Email setup / reset link</button><p class="error" role="alert"></p></form>`:''}<p><a href="${esc(accountStoreUrl())}">Back to the store</a></p>`}
function levelPanel(r,w){if(!r||!r.tier)return '';const tiers=r.tiers.slice().sort((a,b)=>a.min_points-b.min_points),top=tiers[tiers.length-1].min_points,num=n=>Number(n).toLocaleString('en-US'),dbl=r.double_points_until,rate=r.tier.multiplier*(dbl?2:1);
 const pos=c=>Math.min(100,c*100/top),here=pos(r.points_lifetime);
 const card=`<div class="lv-card lv-${esc(r.tier.id)}">${dbl?`<div class="lv-ribbon">✨ Double points until ${esc(untilText(dbl))}</div>`:''}<div class="lv-top"><div><div class="lv-eyebrow">Glow level</div><div class="lv-name">${esc(r.tier.name)}</div><div class="lv-rate">${rate} point${rate===1?'':'s'} per $1${dbl?' right now':''}</div></div><div class="lv-bal"><strong>${w?w.available:0}</strong><span>points · ${money(w?w.value_cents:0)} off</span></div></div><div class="lv-foot">${r.next?`${num(r.next.needed_points)} more points to <b>${esc(r.next.name)}</b>`:'Top level — thank you for being one of our best customers'}</div></div>`;
 const track=`<div class="lv-track" aria-label="Your progress through the Glow levels"><div class="lv-line"><i style="width:${here}%"></i><span class="lv-you" style="left:${here}%" title="You: ${num(r.points_lifetime)} points earned"></span></div>${tiers.map((t,i)=>`<div class="lv-stop${r.points_lifetime>=t.min_points?' on':''}${i===0?' first':''}${i===tiers.length-1?' last':''}" style="left:${pos(t.min_points)}%"><b>${esc(t.name)}</b><small>${t.min_points?num(t.min_points)+' pts':'Start'}</small></div>`).join('')}</div><p class="muted lv-spent">You have earned ${num(r.points_lifetime)} points with us${r.next?` · ${num(r.next.needed_points)} more to ${esc(r.next.name)}`:''}. Using points never lowers your level.</p>`;
 const tiles=`<div class="lv-tiles">${tiers.map(t=>{const mine=t.id===r.tier.id,got=r.points_lifetime>=t.min_points;return `<div class="lv-tile lv-${esc(t.id)}${mine?' mine':''}${got?'':' locked'}"><div class="lv-tile-h">${got?'':'🔒 '}${esc(t.name)}${mine?' <em>You</em>':''}</div><div class="lv-tile-x">${t.multiplier}×</div><div class="lv-tile-s">${t.multiplier} point${t.multiplier===1?'':'s'} per $1 · ${t.multiplier*5}% back</div><div class="lv-tile-s">${t.min_points?'From '+num(t.min_points)+' points earned':'Every account starts here'}</div></div>`}).join('')}</div>`;
 const share=r.bonuses_on&&r.referral_code?`<div class="lv-share"><div><h3>Share Glow, get $10</h3><p>Send a friend your link. When they pay for their first order of $50 or more, you get <strong>${r.referral_bonus} points (${money(r.referral_bonus*5)})</strong>. If they make an account, they get ${r.signup_bonus} points (${money(r.signup_bonus*5)}) too.</p><p class="lv-fine">New customers only: not for people who already have an account or have ordered before, and not for someone at your own address.</p></div><div class="lv-link"><input readonly value="${esc(friendUrl(r.referral_code))}" aria-label="Your friend link">${button('Copy link','copy-friend-link','')}${button('Share','share-friend-link','secondary lv-sharebtn')}</div></div>`:'';
 return `<section class="glow-levels">${card}${track}${tiles}${share}</section>`}
function friendUrl(code){return location.origin+'/store-next/?friend='+encodeURIComponent(code)}
function renderAccount(){const d=state.customer,w=d.wallet;app.innerHTML=`<div class="row"><div><div class="eyebrow">Your customer account</div><h1>Hi, ${esc(d.customer.name)}.</h1>${BR().id==='zader'?'<p><a class="button" href="/store-next/affiliate">My affiliate dashboard / apply</a></p>':''}<p class="muted">${esc(d.customer.email)}</p></div>${button('Sign out','customer-logout','secondary')}</div><div class="metrics"><section class="panel metric"><strong>${w.available}</strong><small>Available points</small></section><section class="panel metric"><strong>${money(w.value_cents)}</strong><small>Available discount</small></section><section class="panel metric"><strong>${w.reserved}</strong><small>Points held for unpaid orders</small></section><section class="panel metric"><strong>${w.balance}</strong><small>Total points balance</small></section></div>${levelPanel(d.rewards,w)}<div class="notice">Points never expire and can be used with up to two eligible promo codes. Earn 1 point for each whole $1 of products after all discounts, excluding shipping and tax — 1.5 points at Gold and 2 at Purple. Each point is worth $0.05. Earned points appear after staff verify payment; test orders do not change your real balance.</div><section class="panel"><h2>Your orders</h2>${d.orders.map(o=>`<div class="row"><span>${esc(o.id)} · ${money(o.total)} · ${esc(orderLabel(o))} · Ordered ${esc(orderTime(o.created))}${o.is_test!==false?' · Test order':''}</span><button data-action="account-order" data-id="${esc(o.id)}" class="secondary">View order</button></div>`).join('')||'<p>No orders associated with this account yet.</p>'}<p class="muted">Paid guest orders placed with this email are added to your account automatically, with their points.</p></section><section class="panel account-ledger"><h2>Your points history</h2>${ledgerTable(d.ledger)}</section><p><a href="${esc(accountStoreUrl())}">Continue shopping</a></p>`}
function loadAccountSetup(){const parts=location.hash.slice(1).split('.');state.setupId=parts[0]||'';state.setupToken=parts[1]||'';history.replaceState(null,'',location.pathname);if(!/^[a-f0-9]{64}$/.test(state.setupId)||!/^[A-Za-z0-9_-]{43}$/.test(state.setupToken)){app.innerHTML='<h1>Account setup link unavailable</h1><p><a href="/store-next/account#customer-forgot">Request a new setup / reset email</a>.</p>';return}app.innerHTML=`<form id="customer-setup" class="panel login-panel"><div class="eyebrow">Private account setup</div><h1>Choose your password.</h1><p>Use a passphrase with 15–128 characters. Completing this private setup verifies the email account the link was sent to.</p><label>New password<input name="password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><label>Confirm password<input name="confirm_password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><button type="submit">Save password and sign in</button><p class="error" role="alert"></p><p class="muted">This link works once and expires after 24 hours. Reloading this page clears the link; reopen the original link if needed.</p></form>`}
function customersAdmin(){const d=state.customerAdmin,p=state.migrationPreview;if(!d)return '<p>Open Customers to load account and rewards records.</p>';return `<section class="panel"><h2>Customer accounts and rewards</h2><div class="notice">1 point per whole $1 of products after all discounts, excluding shipping and tax. Each point is worth $0.05. Points stack with one promo code and never expire. Membership levels are inactive.</div><p>${state.admin.email?.configured?'Use Email setup / reset to send a private link directly to the saved customer address.':'Automatic email delivery is not enabled. Create a private setup / reset link and email it only to the customer address shown.'} The customer chooses their password; completing setup claims any matching imported balance.</p><div id="customer-link-result" aria-live="polite"></div><div class="tablewrap"><table><thead><tr><th>Customer</th><th>Email</th><th>Status</th><th>Available points</th><th>Actions</th></tr></thead><tbody>${d.customers.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.email)}</td><td>${a.verified?'Verified':'Awaiting email setup'}</td><td>${a.wallet.available} · ${money(a.wallet.value_cents)}</td><td><div class="actions"><button data-action="edit-customer-profile" data-id="${a.id}" class="secondary">Edit customer</button>${state.admin.email?.configured?`<button data-action="send-customer-setup" data-id="${a.id}" class="secondary">Email setup / reset</button>`:''}<button data-action="customer-setup-link" data-id="${a.id}" class="secondary">${a.verified?'Password reset link':'Account setup link'}</button>${a.verified?`<button data-action="customer-ledger" data-id="${a.id}" class="secondary">Points history / adjustment</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>${!d.customers.length?'<p>No account requests yet. Customers can request setup at <a href="/store-next/account">the account page</a>.</p>':''}</section><div id="customer-ledger"></div><section class="panel account-ledger"><h2>Carry over WooCommerce balances</h2><p>Upload the saved migration JSON. Preview totals first, then import. Repeating the same file does not add points twice. Review changed source balances below before reconciling. Reconciliation carries over only the change since the previous WooCommerce snapshot and preserves new-store earnings and redemptions. Imported balances stay unclaimed until email setup is completed.</p><form id="rewards-import"><label>Migration JSON file · up to 2 MB<input name="migration" type="file" accept="application/json,.json" required></label><button type="submit">Preview balances</button><p class="error" role="alert"></p></form>${p?`<div class="notice"><strong>${p.count} rows · ${p.points_total} points · ${money(p.points_total*5)}</strong><p>${p.existing_count} already imported · ${p.held.length} held for email review · ${p.missing_redeem_history} missing historical redeemed value.</p>${p.held.map(r=>`<p>${esc(r.email)} — ${esc(r.reason)}</p>`).join('')}${p.conflicts.length?`<p><strong>Source changes to review: ${p.points_delta} points difference.</strong></p>${p.changes.map(r=>`<p>${esc(r.email)}: ${r.previous_points} → ${r.points} points (${r.delta>=0?'+':''}${r.delta})</p>`).join('')}${button('Reconcile these source balances','reconcile-rewards-import')}`:button('Import these balances','commit-rewards-import') }</div>`:''}<h3>${d.imports.length} imported balances</h3><p>${d.imports.filter(r=>r.claimed).length} claimed · ${d.imports.filter(r=>r.held).length} held for review</p><div class="tablewrap"><table><thead><tr><th>Email</th><th>Points</th><th>Redeemed history</th><th>Status</th></tr></thead><tbody>${d.imports.map(r=>`<tr><td>${esc(r.email)}</td><td>${r.points}</td><td>${r.redeem_points===null?'Missing':r.redeem_points}</td><td>${r.held?'Held for email review':r.claimed?'Claimed':'Awaiting verified account'}</td></tr>`).join('')}</tbody></table></div></section>`}
if(/\/store-next\/(account(?:-setup)?|profile\/[a-z0-9-]+)\/?$/.test(location.pathname))api('/api/catalog').then(d=>renderMode(d.settings)).catch(()=>{});
(/\/store-next\/affiliate\/?$/.test(location.pathname)?loadNativePortal():/\/store-next\/staff-reset\/?$/.test(location.pathname)?Promise.resolve(renderStaffReset()):/\/store-next\/account-setup\/?$/.test(location.pathname)?Promise.resolve(loadAccountSetup()):/\/store-next\/account\/?$/.test(location.pathname)?loadAccount():/\/store-next\/profile\/[a-z0-9-]+\/?$/.test(location.pathname)?loadProfile():/\/store-next\/admin\/?$/.test(location.pathname)?loadAdmin():loadStore()).catch(err=>{app.innerHTML=`<h1>Unable to load the store</h1><p class="error">${esc(err.message)}</p>`});

document.addEventListener('input',e=>{if(e.target.id==='order-search'){state.orderSearch=e.target.value;document.querySelector('#order-results').innerHTML=orderRows()}});
document.addEventListener('change',e=>{if(['order-status','order-mode'].includes(e.target.id)){state[e.target.id==='order-status'?'orderStatus':'orderMode']=e.target.value;document.querySelector('#order-results').innerHTML=orderRows()}});

function staffPanel(){return `<section class="panel"><h2>Staff access</h2><p>Each staff member has their own email and password. Choose full management or Affiliate Manager access. Affiliate Managers can manage Glow storefronts and photo links, including adding and disabling affiliates, without access to orders or financials. Only your owner login can invite staff or remove access.</p><form id="staff-invite"><div class="fields"><label>Name<input name="name" required maxlength="150"></label><label>Email<input name="email" type="email" required maxlength="150"></label></div><label>Access level<select name="role"><option value="affiliate_manager">Affiliate Manager — affiliates and photo links only</option><option value="full">Full store management — includes financials</option></select></label><button type="submit">Send staff invitation</button><p class="error" role="alert"></p></form><div class="tablewrap"><table><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Access</th><th>Action</th></tr></thead><tbody>${(state.admin.staff||[]).map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.email)}</td><td>${!a.active?'Removed':a.verified?'Ready to sign in':'Awaiting password setup'}</td><td>${esc(a.access)}</td><td>${a.active?`<button class="danger" data-action="revoke-staff" data-id="${a.id}">Remove access</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`}
function loadStaffSetup(){const match=location.hash.match(/^#staff=([a-f0-9]{64})\.([A-Za-z0-9_-]{43})$/);history.replaceState(null,'',location.pathname);if(!match){app.innerHTML='<h1>Management setup link unavailable</h1>';return}state.staffSetupId=match[1];state.staffSetupToken=match[2];app.innerHTML=`<form id="staff-setup" class="panel login-panel"><div class="eyebrow">Private management setup</div><h1>Choose your management password.</h1><p>This gives you full store-management access. Use a passphrase with 15–128 characters.</p><label>New password<input name="password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><label>Confirm password<input name="confirm_password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><button type="submit">Save password and open management</button><p class="error" role="alert"></p></form>`}

async function beginCheckoutEdit(){const d=await api('/api/orders/'+state.order.id+'/edit-context',undefined,state.token);state.catalog={products:d.products,settings:d.settings};state.order=d.order;state.editingOrderId=d.order.id;state.cart=new Map(d.order.items.map(i=>[i.id,i.quantity]));state.coupon=Array.isArray(d.order.coupons)?d.order.coupons.join(','):d.order.coupon||'';state.points=d.order.points_redeemed||0;state.affiliate=d.order.affiliate||'';state.orderForCustomer=d.order.order_for_customer===true;state.checkoutValues={...d.order.customer,payment_method:d.order.payment_method};await calculate()}

function renderStaffReset(){app.innerHTML=`<div class="intro"><div class="eyebrow">Private management</div><h1>Reset your staff password.</h1><p>Use the email address on your staff invitation. The private email link works once and expires in 24 hours.</p></div><form id="staff-reset" class="panel login-panel"><label>Management email<input name="email" type="email" required autocomplete="email" maxlength="150"></label><button type="submit">Email password reset link</button><p class="error" role="alert"></p><p class="muted">Check your inbox and spam folder. If you have never received a management invitation, ask the owner to invite you first.</p></form><p><a href="/store-next/admin">Back to management sign-in</a></p>`}


function orderCustomerForm(o){return `<details><summary>Edit customer contact and shipping details</summary><form id="order-customer-edit" autocomplete="off"><input name="id" type="hidden" value="${esc(o.id)}"><input name="expected_revision" type="hidden" value="${o.revision||0}"><div class="fields">${[['name','Full name','text'],['email','Order contact email','email'],['phone','Phone number','tel'],['address','Street address','text'],['city','City','text'],['state','State / territory','text'],['zip','ZIP code','text']].map(([key,label,type])=>`<label>${label}<input name="${key}" type="${type}" autocomplete="off" value="${esc(o.customer[key]||'')}" required maxlength="${key==='address'?500:key==='phone'?32:150}"></label>`).join('')}</div><p class="muted">These changes apply to this order. The customer’s sign-in and rewards account stay linked to their original account.</p>${o.shipstation_order_id?'<label><input type="checkbox" name="shipping_review"> I will also update any changed shipping details in ShipStation.</label>':''}${o.shipstation_needs_review?'<p class="error">Shipping details changed after export. Update this shipment in ShipStation.</p>':''}<button type="submit">Save customer details</button><p class="error" role="alert"></p></form></details>`}
function customerProfileForm(a){return `<section class="panel"><h2>Edit ${esc(a.name)}</h2><form id="customer-profile-edit"><input name="customer_id" type="hidden" value="${esc(a.id)}"><input name="expected_revision" type="hidden" value="${a.profile_revision||0}"><label>Customer name<input name="name" value="${esc(a.name)}" required maxlength="150"></label><label>Phone number<input name="phone" type="tel" value="${esc(a.phone||'')}" maxlength="32"></label><p>Sign-in email: ${esc(a.email)}</p><p class="muted">To change an order’s email or shipping address, open that order and edit its customer details.</p><button type="submit">Save customer profile</button><p class="error" role="alert"></p></form></section>`}
setInterval(()=>{document.querySelectorAll('[data-order-age]').forEach(el=>{el.textContent=orderAge(Number(el.dataset.orderAge))})},60000);

function orderCents(value){const n=String(value).trim();if(!/^\d+(?:\.\d{1,2})?$/.test(n))throw new Error('Enter a dollar amount with up to two decimal places.');return Math.round(Number(n)*100)}
function orderItemRow(i){return `<div class="fields line" data-order-product="${i.id}"><strong>${esc(i.name)}</strong><button type="button" data-action="remove-order-item" class="secondary" aria-label="Remove ${esc(i.name)}">Remove item</button><label>Quantity (0 removes)<input data-quantity type="number" min="0" max="100" step="1" value="${i.quantity}" required></label><label>Unit price ($)<input data-price type="number" min="0" step="0.01" value="${(i.price/100).toFixed(2)}" required></label></div>`}
function orderEditPayload(f){if(![...f.querySelectorAll('[data-order-product]')].some(row=>Number(row.querySelector('[data-quantity]').value)>0))throw new Error('Keep at least one item, or cancel the order instead.');return{id:f.elements.id.value,expected_revision:Number(f.elements.expected_revision.value),items:[...f.querySelectorAll('[data-order-product]')].map(row=>({id:Number(row.dataset.orderProduct),quantity:Number(row.querySelector('[data-quantity]').value),price:orderCents(row.querySelector('[data-price]').value)})).filter(i=>i.quantity!==0),coupon_discount:orderCents(f.elements.coupon_discount.value),shipping:orderCents(f.elements.shipping.value),tax:orderCents(f.elements.tax.value),reason:f.elements.reason.value}}
function updateOrderEditPreview(f){const node=f.querySelector('#order-edit-preview');try{const b=orderEditPayload(f),o=state.admin.orders.find(o=>o.id===b.id),subtotal=b.items.reduce((n,i)=>n+i.quantity*i.price,0),total=subtotal-b.coupon_discount-(o.rewards_discount||0)+b.shipping+b.tax,verified=o.paid?(o.verified_payment_cents??o.total):0;node.textContent='Updated total: '+money(total)+(o.paid?' · Verified payment: '+money(verified)+(total>verified?' · Additional payment due: '+money(total-verified):total<verified?' · Refund owed: '+money(verified-total):' · Fully paid'):'');}catch{node.textContent='Complete quantities and dollar amounts to preview the total.'}}
function orderItemsForm(o){if(!['order_received','awaiting_payment','payment_submitted','paid'].includes(o.status))return '<p class="notice">'+(o.status==='expired'?'Reinstate this expired order before changing its items.':'Items on shipped or canceled orders are locked. You can still update contact details and add staff notes.')+'</p>';return `<details open><summary>Edit products, quantities and pricing</summary><form id="order-items-edit"><input type="hidden" name="id" value="${esc(o.id)}"><input type="hidden" name="expected_revision" value="${o.revision||0}"><p>Add products below, change quantities or prices, or use Remove item. Nothing changes until you save. Existing prices are kept unless you change them. Changes update inventory together with the order.</p><div id="order-edit-lines">${o.items.map(orderItemRow).join('')}</div><div class="actions"><label>Add a product<select name="add_product"><option value="">Choose a product</option>${state.admin.products.filter(p=>p.active).sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${p.id}">${esc(p.name)} · ${money(p.price)} · ${p.components&&p.components.length?adminAvail(p)+' bundles':p.units>1?Math.floor(p.stock/p.units)+' kits':p.stock} available</option>`).join('')}</select></label>${button('Add product','add-order-item','secondary')}</div><div class="fields">${[['coupon_discount','Promo / manual discount ($)',o.coupon_discount??Math.max(0,o.discount-(o.rewards_discount||0))],['shipping','Shipping ($)',o.shipping],['tax','Tax ($)',o.tax]].map(([key,label,cents])=>`<label>${label}<input name="${key}" type="number" min="0" step="0.01" value="${(cents/100).toFixed(2)}" required></label>`).join('')}</div><p>Rewards discount: ${money(o.rewards_discount||0)}. The original rewards redemption and affiliate attribution are preserved. Promo discounts are dollar amounts here; review them when changing items.</p><label>Reason for adjustment<textarea name="reason" required maxlength="500" placeholder="Customer requested an additional product"></textarea></label><p id="order-edit-preview" aria-live="polite">Current total: ${money(o.total)}</p>${o.shipstation_order_id||o.goaffpro_status==='synced'||o.goaffpro_needs_review?'<div class="notice">This order has already been exported. After saving, update its existing shipment and affiliate sale in ShipStation / GoAffPro. Changes are flagged for review.</div>':''}<button type="submit">Save order adjustments</button><p class="error" role="alert"></p></form></details>`}
function orderBalance(o,management=false){if(!o.paid)return '';const payment=o.verified_payment_cents??o.total,due=o.balance_due_cents||0,refund=o.refund_due_cents||0;return `<section class="notice"><p>Verified payment: ${money(payment)} · Current order total: ${money(o.total)}</p>${due?`<strong>Additional payment due: ${money(due)}</strong><p>Only the difference is due. The original payment remains recorded. Additional rewards and shipping wait until staff verify the balance.</p>`:refund?`<strong>Refund owed: ${money(refund)}</strong><p>The adjustment records a refund owed; it does not send money automatically.</p>`:'<p>Fully paid · no additional payment due.</p>'}${management&&(due||refund)?`<form id="order-payment-adjustment"><input name="id" type="hidden" value="${esc(o.id)}"><input name="expected_revision" type="hidden" value="${o.revision||0}"><input name="kind" type="hidden" value="${refund?'refund':'payment'}"><label>${refund?'Refund sent':'Additional payment received'} ($)<input name="amount" type="number" min="0.01" max="${((due||refund)/100).toFixed(2)}" step="0.01" value="${((due||refund)/100).toFixed(2)}" required></label><label>Reference / note<input name="reason" required maxlength="500"></label><label><input name="verified" type="checkbox" required> I verified the ${refund?'refund was sent':'additional funds were received'} in the payment account.</label><button type="submit">Record verified ${refund?'refund':'payment'}</button><p class="error" role="alert"></p></form>`:''}</section>`}
document.addEventListener('input',e=>{const f=e.target.closest('#order-items-edit');if(f)updateOrderEditPreview(f)});

function orderExportReview(o){if(!o.shipstation_needs_review&&!o.goaffpro_needs_review)return '';return `<form id="order-export-review" class="notice"><h3>External order changes need review</h3><p>Update the existing order in each service, including changed items, total and commission. This button records your confirmation; it does not edit those services for you.</p><input name="id" type="hidden" value="${esc(o.id)}"><input name="expected_revision" type="hidden" value="${o.revision||0}">${o.shipstation_needs_review?'<label><input name="shipping_review" type="checkbox"> I updated and reviewed the existing ShipStation order.</label>':''}${o.goaffpro_needs_review?'<label><input name="affiliate_review" type="checkbox"> I updated and reviewed the existing GoAffPro sale and commission.</label>':''}<button type="submit">Confirm external updates</button><p class="error" role="alert"></p></form>`}

function matchesOrderStatus(o,status){if(status==='checkout_drafts')return isCheckoutDraft(o);if(isCheckoutDraft(o))return false;if(status==='all')return true;if(status==='balance_due')return o.status==='paid'&&o.balance_due_cents>0;if(status==='refund_due')return o.status==='paid'&&o.refund_due_cents>0;if(status==='paid')return o.status==='paid'&&!o.balance_due_cents&&!o.refund_due_cents;return o.status===status}










// Zader's first-party affiliate workspace. Existing verified customer authentication is reused.
function nativeRestoreReferral(){if(BR().id!=='zader')return;try{const r=JSON.parse(localStorage.getItem('zader_referral')||'null');if(r&&r.expires>Date.now()&&/^[a-z0-9-]{1,60}$/.test(r.slug))sessionStorage.setItem('glow_customer_store',r.slug);else{localStorage.removeItem('zader_referral');sessionStorage.removeItem('glow_customer_store')}}catch{}}
function nativeRememberReferral(){if(BR().id!=='zader'||!state.affiliate)return;try{const old=JSON.parse(localStorage.getItem('zader_referral')||'null'),explicit=new URLSearchParams(location.search).has('ref')||location.pathname!=='/store-next/'&&location.pathname!=='/';if(explicit||!old||old.slug!==state.affiliate)localStorage.setItem('zader_referral',JSON.stringify({slug:state.affiliate,expires:Date.now()+30*86400000}))}catch{}}
function nativeLedger(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>When</th><th>Activity</th><th>Order / reference</th><th>Amount</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(orderTime(e.created))}</td><td>${esc(e.kind.replaceAll('_',' '))}</td><td>${esc(e.order_id||e.reference||'')}</td><td>${money(e.cents)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No commission or payout entries yet.</p>'}
function nativeAdminPanel(){const d=state.admin.native_affiliates||{affiliates:[]},rows=d.affiliates;return `<section class="panel"><div class="eyebrow">Zader Health · Your own affiliate program</div><h2>Affiliates & commissions</h2><p>No GoAffPro account is needed. Approve each affiliate and choose their commission rate before their storefront becomes active.</p><p><a href="/store-next/affiliate" target="_blank" rel="noopener">Open the affiliate application / dashboard</a></p><div class="notice">Commission is earned on product totals after all discounts, excluding shipping and tax, after staff verify payment. Self-purchases and test orders do not earn commission. Order changes and refunds adjust the ledger. Payouts below record money already sent outside this website.</div><div class="tablewrap"><table><thead><tr><th>Affiliate</th><th>Status / rate</th><th>Net earned</th><th>Paid</th><th>Balance</th><th>Actions</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.name)}<br><small>${esc(a.email)}</small><br><a href="${esc(a.storefront_url)}" target="_blank" rel="noopener">${esc(a.slug)}</a></td><td>${esc(a.status)} · ${a.commission_bps===null?'Rate not set':(a.commission_bps/100)+'%'}</td><td>${money(a.earned_cents)}</td><td>${money(a.paid_cents)}</td><td>${money(a.balance_cents)}</td><td><button type="button" class="secondary" data-action="native-edit" data-slug="${esc(a.slug)}">Edit / approve</button> <button type="button" class="secondary" data-action="native-invite" data-slug="${esc(a.slug)}">Email account setup / reset</button><details><summary>Ledger</summary>${nativeLedger(a.ledger)}</details></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<p>No affiliates yet. Add the first affiliate below or share the application page.</p>'}</section><div class="split"><form id="native-affiliate-save" class="panel"><h3>Add or update an affiliate</h3><input name="expected_revision" type="hidden"><label>Display name<input name="name" required maxlength="150"></label><label>Affiliate email<input name="email" type="email" required maxlength="150"></label><label>Storefront slug<input name="slug" required maxlength="60" pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="zader-jane-smith"></label><label>Short introduction<textarea name="bio" maxlength="500"></textarea></label><label>Commission rate (%)<input name="commission_rate" type="number" min="0" max="100" step="0.01" placeholder="Choose your rate"></label><label>Status<select name="status"><option value="pending">Pending approval</option><option value="approved">Approved / active</option><option value="disabled">Disabled</option></select></label><p class="muted">Set a rate before approving. The slug and account email are fixed after creation. Rate changes apply to new checkouts; existing orders retain their saved rate.</p><button type="submit">Save affiliate</button><button type="button" class="secondary" data-action="native-new">Clear / add another</button><p class="error" role="alert"></p></form><form id="native-payout" class="panel" data-key="${crypto.randomUUID()}"><h3>Record an external commission payout</h3><p>This records a payment you already completed. It does not send funds or create store credit.</p><label>Affiliate<select name="slug" required><option value="">Choose an affiliate</option>${rows.filter(a=>a.balance_cents>0).map(a=>`<option value="${esc(a.slug)}">${esc(a.name)} · ${money(a.balance_cents)} available</option>`).join('')}</select></label><label>Amount paid ($)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Payment method<select name="method"><option>PayPal</option><option>Venmo</option><option>Cash App</option><option>Zelle</option><option>Bank transfer</option><option>Other external payment</option></select></label><label>Unique transaction reference<input name="reference" required maxlength="200"></label><label class="check"><input name="confirmed" type="checkbox" required> I verified this payment was completed outside the website.</label><button type="submit" ${rows.some(a=>a.balance_cents>0)?'':'disabled'}>Record completed payout</button><p class="error" role="alert"></p></form></div>`}
async function loadNativePortal(){state.admin=null;state.catalog=await api('/api/catalog');if(BR().id!=='zader')return loadStore();renderMode(state.catalog.settings);try{state.customer=await api('/api/account')}catch{state.customer=null;renderAccountLogin();app.insertAdjacentHTML('afterbegin','<section class="notice"><h1>Zader Health affiliate program</h1><p>Sign in or request an account below. After verifying your email, open My affiliate dashboard to apply or manage your storefront.</p></section>');return}state.nativePortal=await api('/api/native-affiliates');renderNativePortal()}
function renderNativePortal(){const d=state.nativePortal,a=d.affiliate;app.innerHTML=`<div class="intro"><div class="eyebrow">Zader Health</div><h1>Your affiliate workspace.</h1><p><a href="/store-next/account">My account</a> · <a href="/store-next/">Shop Zader Health</a></p></div>${!a?`<form id="native-apply" class="panel"><h2>Apply to become an affiliate</h2><p>Your verified account email is ${esc(state.customer.customer.email)}. Staff will review your application and set your commission rate. Your storefront stays inactive until approval.</p><label>Preferred storefront slug<input name="slug" required maxlength="60" pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="zader-jane-smith"></label><label>Tell customers about yourself<textarea name="bio" maxlength="500"></textarea></label><button type="submit">Submit application</button><p class="error" role="alert"></p></form>`:`<section class="panel"><h2>${esc(a.name)}</h2><p>Status: <strong>${esc(a.status)}</strong> · Commission: <strong>${a.commission_bps===null?'Not configured':(a.commission_bps/100)+'%'}</strong></p>${a.active?`<label>Your personalized storefront / referral link<input readonly value="${esc(a.storefront_url)}" aria-label="Your storefront link"></label><p><a href="${esc(a.storefront_url)}" target="_blank" rel="noopener">View my storefront</a></p>`:'<p>Your storefront is inactive. Staff approval and a configured rate are required before you share it.</p>'}${d.coupons?.length?`<h3>Your customer discount codes</h3>${d.coupons.map(c=>`<p><strong>${esc(c.code)}</strong> · ${c.kind==='percent'?c.value+'%':money(c.value)} off · ${c.allow_stacking?'Can combine with one eligible coupon':'Use on its own'}</p>`).join('')}`:'<p>No customer discount code has been assigned yet. Staff can create one in Coupons.</p>'}<p>Referral links are remembered for up to 30 days on the same browser when storage is available. A later affiliate link replaces the earlier link; an affiliate coupon takes priority. Commissions are based on verified product payments after discounts, excluding shipping and tax.</p></section><div class="metrics"><section class="panel metric"><strong>${money(d.balance_cents)}</strong><small>Commission balance${d.balance_cents<0?' · adjustment owed':''}</small></section><section class="panel metric"><strong>${money(d.earned_cents)}</strong><small>Net commissions earned</small></section><section class="panel metric"><strong>${money(d.paid_cents)}</strong><small>Payouts recorded</small></section></div><div class="split"><form id="native-profile" class="panel"><h2>Your public profile</h2><input name="expected_revision" type="hidden" value="${a.revision}"><label>Public display name<input name="name" required maxlength="150" value="${esc(a.name)}"></label><label>Short introduction<textarea name="bio" maxlength="500">${esc(a.bio)}</textarea></label><button type="submit">Save profile</button><p class="error" role="alert"></p></form><form id="native-photo" class="panel"><h2>Professional headshot</h2>${a.photo_url?`<img class="affiliate-avatar profile-avatar" src="${esc(a.photo_url)}&v=${Date.now()}" alt="Your storefront photo">`:''}<label>JPEG, PNG or WebP · up to 3 MB<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></label><p>Your photo is cropped to a square. Keep your face near the center.</p><button type="submit">Upload photo</button>${a.photo_url?'<button type="button" class="secondary" data-action="native-remove-photo">Remove photo</button>':''}<p class="error" role="alert"></p></form></div><section class="panel"><h2>Your referral orders</h2><p>Unpaid or unsettled orders do not add to your available commission. Customer contact and shipping information are private.</p><div class="tablewrap"><table><thead><tr><th>Order</th><th>Status</th><th>Net products</th><th>Earned commission</th><th>Potential unpaid commission</th></tr></thead><tbody>${d.orders.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(o.status.replaceAll('_',' '))}</td><td>${money(o.product_net_cents)}</td><td>${money(o.commission_cents)}</td><td>${money(o.pending_commission_cents)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Commission & payout ledger</h2>${nativeLedger(d.ledger)}</section>`}`}
async function nativeClick(action,b){if(action==='native-clear-referral'){clearNativeReferral();await calculate();renderBag();toast('Affiliate referral and promo codes removed.')}else if(action==='native-edit'){const a=state.admin.native_affiliates.affiliates.find(a=>a.slug===b.dataset.slug),f=document.querySelector('#native-affiliate-save');fill(f,{...a,expected_revision:a.revision,commission_rate:a.commission_bps===null?'':a.commission_bps/100});f.elements.slug.readOnly=true;f.elements.email.readOnly=true;f.scrollIntoView({behavior:'smooth',block:'start'})}else if(action==='native-new'){state.tab='affiliates';renderAdmin()}else if(action==='native-invite'){await api('/api/admin/native-affiliates/invite',{slug:b.dataset.slug});toast('Account setup / reset email requested. Check Emails for delivery status.')}else if(action==='native-remove-photo'){await api('/api/native-affiliates/photo',{remove:true});await loadNativePortal()}}
async function nativeSubmit(id,f,v){if(id==='native-affiliate-save'){const rate=v.commission_rate===''?null:Math.round(Number(v.commission_rate)*100);await api('/api/admin/native-affiliates/save',{name:v.name,email:v.email,slug:v.slug,bio:v.bio,commission_bps:rate,status:v.status,...(v.expected_revision?{expected_revision:Number(v.expected_revision)}:{})});state.tab='affiliates';await loadAdmin();toast('Zader affiliate saved.')}else if(id==='native-payout'){await api('/api/admin/native-affiliates/payout',{slug:v.slug,amount_cents:reportCents(v.amount),method:v.method,reference:v.reference,idempotency_key:f.dataset.key,confirmed:f.elements.confirmed.checked});await loadAdmin();toast('Completed payout recorded. No funds were transferred by the website.')}else if(id==='native-apply'){await api('/api/native-affiliates/apply',{slug:v.slug,bio:v.bio});await loadNativePortal();toast('Application saved for staff review.')}else if(id==='native-profile'){await api('/api/native-affiliates/profile',{name:v.name,bio:v.bio,expected_revision:Number(v.expected_revision)});await loadNativePortal();toast('Profile saved.')}else if(id==='native-photo'){const file=f.elements.photo.files[0];if(!file||file.size>3*1024*1024)throw new Error('Choose a photo up to 3 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Could not read this photo.'));reader.readAsDataURL(file)});await api('/api/native-affiliates/photo',{mime:file.type,file:data});await loadNativePortal();toast('Storefront photo saved.')}}

function clearNativeReferral(){state.affiliate='';state.affiliateProfile=null;state.coupon='';try{sessionStorage.removeItem('glow_customer_store');sessionStorage.removeItem('glow_referral');localStorage.removeItem('zader_referral')}catch{}}


function orderNotesForm(o){return `<section class="panel"><h3>Private staff notes</h3><p class="muted">For you and your staff. Notes do not appear in customer emails, order pages or packing slips.</p>${(o.staff_notes||[]).map(n=>`<div class="notice"><p class="muted">${esc(n.author)} · ${esc(orderTime(n.created))}</p><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(n.text)}</p></div>`).join('')||'<p>No staff notes yet.</p>'}<form id="order-staff-note"><input type="hidden" name="id" value="${esc(o.id)}"><input type="hidden" name="key" value="${crypto.randomUUID()}"><label>Add a staff note<textarea name="note" required maxlength="2000" rows="3" placeholder="Customer requests, order changes, or follow-up details"></textarea></label><button type="submit">Save staff note</button><p class="error" role="alert"></p></form></section>`}


function renderAffiliateManager(){const d=state.admin,banner=document.querySelector('.demo');if(banner)banner.textContent='GLOW LAB · Affiliate Manager';document.title='Affiliate Manager · Glow Lab';app.innerHTML=`<div class="row"><div><div class="eyebrow">Private management · Glow Lab</div><h1>Affiliate Manager</h1><p>Manage affiliate storefronts and private photo-upload links.</p></div>${button('Sign out','logout','secondary')}</div><div class="split"><section class="panel"><h2>Affiliate storefronts</h2><div id="photo-link-result" aria-live="polite"></div><p>Disabling removes the storefront from shopping and revokes its photo-upload link. Historical orders are kept. This does not block the affiliate’s separate GoAffPro account.</p>${d.affiliates.map(a=>`<div class="line"><div class="row"><strong>${esc(a.name)}</strong><span class="badge">${a.active?'Active':'Disabled'}</span></div><p><a href="/store-next/${esc(a.slug)}" target="_blank" rel="noopener">${esc(location.origin)}/store-next/${esc(a.slug)}</a></p><div class="actions">${a.active?`<button data-action="copy-storefront" data-slug="${esc(a.slug)}" class="secondary">Copy store link</button><button data-action="photo-link" data-slug="${esc(a.slug)}" class="secondary">Photo upload link</button>`:''}<button data-action="edit-affiliate" data-slug="${esc(a.slug)}" class="secondary">Edit</button><button data-action="affiliate-status" data-slug="${esc(a.slug)}" class="${a.active?'danger':'secondary'}">${a.active?'Disable affiliate':'Restore affiliate'}</button></div></div>`).join('')||'<p>No affiliate storefronts yet.</p>'}</section><form id="affiliate" class="panel"><div class="row"><h2 id="affiliate-title">Add an affiliate</h2>${button('New affiliate','new-managed-affiliate','secondary')}</div><input name="expected_revision" type="hidden" value="">${field('slug','Store link slug (e.g. sarah)')}${field('name','Display name')}<label>Introduction<textarea name="bio" maxlength="500"></textarea></label>${field('goaffpro_id','GoAffPro affiliate ID')}<p class="muted">Use the ID of an approved affiliate from your store owner. Existing store links and GoAffPro IDs stay fixed.</p><label>Status<select name="active"><option value="1">Active</option><option value="0">Disabled</option></select></label><button type="submit">Save affiliate</button><p class="error" role="alert"></p></form></div>`}
// Back navigation for the shop (Jonah, 25 Oct 2026). The bag, checkout and order pages are drawn inside one page, so the phone or browser Back button used to leave the store entirely, and the card-invoice page had no way back. Each step now gets a history entry: Back from checkout returns to the bag, Back from the bag returns to the store, and Back (or the "← Back to store" button) from any checkout/order page reloads the store, which shows "Resume checkout" so nothing is lost and no second order can be started from a stale bag.
(function(){if(typeof window==='undefined'||!window.history||typeof renderOrder!=='function'||typeof renderStore!=='function')return;const depth={store:0,bag:1,checkout:2,order:3};let cur='store',popping=false;const mark=v=>{if(popping){cur=v;return}if(v!=='store'){try{const st={glowView:v};if(depth[v]>depth[cur])history.pushState(st,'',location.href);else history.replaceState(st,'',location.href)}catch{}}cur=v};const wrap=(f,v,ok)=>function(){const r=f.apply(this,arguments);if(!ok||ok())mark(v);if(v==='order')addBack();return r};const addBack=()=>{const a=document.getElementById('app');if(a&&!a.querySelector('[data-action="back-to-store"]'))a.insertAdjacentHTML('afterbegin','<p class="back-to-store"><button type="button" class="secondary" data-action="back-to-store">← Back to store</button></p>')};const reloadStore=()=>location.assign(location.pathname+(location.search||''));const hasOrder=()=>!!(state.order||state.editingOrderId||sessionStorage.getItem('glow_order'));
renderStore=wrap(renderStore,'store');renderBag=wrap(renderBag,'bag');checkout=wrap(checkout,'checkout',()=>!!document.querySelector('#checkout'));renderOrder=wrap(renderOrder,'order');
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="back-to-store"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(hasOrder())reloadStore();else{renderStore();scrollTo(0,0)}},true);
window.addEventListener('popstate',()=>{if(cur==='store')return;if(cur==='order'||hasOrder()){reloadStore();return}popping=true;try{if(cur==='checkout'){const f=document.querySelector('#checkout');if(f)state.checkoutValues=Object.fromEntries(new FormData(f));renderBag()}else{renderStore()}scrollTo(0,0)}finally{popping=false}})})();


function productPriceHtml(p){const sale=p.intro_active&&p.regular_price>p.price;return `<span class="product-offer-price">${sale?`<del class="regular-price" aria-label="Regular price">${money(p.regular_price)}</del>`:''}<span class="price">${money(p.price)}</span>${sale?'<small>Introductory price</small>':''}</span>`}
function newProductSpotlight(){if(BR().id!=='glow')return '';const products=state.catalog.products.filter(p=>p.active!==0&&p.spotlight);if(!products.length)return '';return `<section class="product-spotlight" aria-labelledby="product-spotlight-title"><div class="section-heading"><div><div class="eyebrow">Discover what’s new</div><h2 id="product-spotlight-title">New Product Spotlight</h2></div></div>${products.map(p=>`<article class="product-spotlight-card" data-spotlight-product="${p.id}">${p.image?`<div class="spotlight-photo"><img src="${esc(p.image)}" alt="${esc(p.name)}" width="960" height="960" loading="eager"></div>`:''}<div class="spotlight-copy"><span class="spotlight-badge">${p.intro_active?'Introductory offer':'New arrival'}</span><h3>${esc(p.spotlight_headline||p.name)}</h3>${p.spotlight_headline&&p.spotlight_headline!==p.name?`<p class="muted">${esc(p.name)}</p>`:''}${p.spotlight_copy?`<p class="spotlight-description">${esc(p.spotlight_copy)}</p>`:''}${productPriceHtml(p)}${p.intro_active&&p.regular_price>p.price?`<p class="spotlight-saving">Save ${money(p.regular_price-p.price)}</p>`:''}${p.spotlight_note?`<p class="spotlight-note">${esc(p.spotlight_note)}</p>`:''}<p class="stock">${p.stock?'In stock':'Sold out'}</p>${p.promo_excluded?'<p class="muted">Special price · promo codes do not apply</p>':''}<button type="button" data-action="add" data-id="${p.id}" ${p.stock?'':'disabled'}>${p.stock?'Add to bag':'Out of stock'}</button></div></article>`).join('')}</section>`}
function productOfferFields(){return `<fieldset class="product-offer-fields"><legend>New Product Spotlight & introductory price</legend><input name="expected_offer_revision" type="hidden" value="0"><label>Introductory price ($)<input name="intro_price" type="number" min="0" step="0.01" placeholder="Leave blank for no introductory offer"></label><label>Introductory offer<select name="intro_active"><option value="0">Off — charge the regular price</option><option value="1">On — charge the introductory price</option></select></label><label>Homepage spotlight<select name="spotlight"><option value="0">Not featured</option><option value="1">Feature in New Product Spotlight</option></select></label><label>Spotlight heading<input name="spotlight_headline" maxlength="120" placeholder="Product name if blank"></label><label>Spotlight description<textarea name="spotlight_copy" maxlength="600" rows="3"></textarea></label><label>Offer note<input name="spotlight_note" maxlength="150" placeholder="While supplies last"></label><p class="muted">The active price is used everywhere, including checkout. Turning off the introductory offer restores the regular price. Stock is shared with the catalog listing, so sold-out products cannot be added. Coupon eligibility is controlled separately below.</p></fieldset>`}
